using System.Text.Json;
namespace AssetFlow.Agent;
public sealed record AgentOptions(string ApiUrl,string RegistrationToken,string? DeviceToken=null,string? AgentId=null,int CollectionMinutes=60);
public sealed class AgentState{private static readonly string Dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"AssetFlow");private static readonly string PathName=Path.Combine(Dir,"agent.json");public AgentOptions Options{get;private set;}public AgentState(){Directory.CreateDirectory(Dir);Options=File.Exists(PathName)?JsonSerializer.Deserialize<AgentOptions>(File.ReadAllText(PathName))??Defaults():Defaults();}public void Save(AgentOptions value){Options=value;File.WriteAllText(PathName,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}));}private static AgentOptions Defaults()=>new(Environment.GetEnvironmentVariable("ASSETFLOW_API_URL")??"http://localhost:18080",Environment.GetEnvironmentVariable("ASSETFLOW_REGISTRATION_TOKEN")??"change-me");}
